mapper.sql:
WHERE purchase_requests.status > 0

  AND (
  vendors.name LIKE CONCAT('%', #{filter.searchText}, '%')

  OR purchase_requests.pr_code LIKE CONCAT('%', #{filter.searchText}, '%')

  OR (
  SELECT GROUP_CONCAT(order_code SEPARATOR ', ')
  FROM orders
  WHERE id IN (
  SELECT order_id
  FROM purchase_request_orders
  WHERE purchase_request_id = purchase_requests.id
  )


  ) LIKE CONCAT('%', #{filter.searchText}, '%')
  OR (
  SELECT GROUP_CONCAT(so_code SEPARATOR ', ')
  FROM sales_orders
  WHERE order_id IN (
  SELECT id
  FROM orders
  WHERE id IN (
  SELECT order_id
  FROM purchase_request_orders
  WHERE purchase_request_id = purchase_requests.id
  )
  )
  ) LIKE CONCAT('%', #{filter.searchText}, '%')
  )




  AND purchase_requests.order_date >= #{filter.dateFrom}


  AND purchase_requests.order_date <= #{filter.dateTo}


  AND purchase_requests.status = #{filter.status}

mapper.select:
SELECT purchase_requests.id AS id, purchase_requests.order_date AS poDate, purchase_requests.pr_code AS poNo, CASE WHEN purchase_requests.pv_request_id IS NOT NULL AND purchase_requests.status IN (1,2) THEN 1 ELSE 0 END AS hasEr, IFNULL(( SELECT GROUP_CONCAT(order_code SEPARATOR ', ') FROM orders WHERE id IN ( SELECT order_id FROM purchase_request_orders WHERE purchase_request_id = purchase_requests.id ) ), '') AS soNo, IFNULL(( SELECT GROUP_CONCAT(so_code SEPARATOR ', ') FROM sales_orders WHERE order_id IN ( SELECT id FROM orders WHERE id IN ( SELECT order_id FROM purchase_request_orders WHERE purchase_request_id = purchase_requests.id ) ) ), '') AS invoiceNo, vendors.name AS vendorName, IFNULL(purchase_requests.total_amount, 0) + IFNULL(purchase_requests.total_vat, 0) AS totalAmount, IFNULL(purchase_requests.total_deposit, 0) AS totalDeposit, purchase_requests.expected_delivery_date AS expectedDeliveryDate, purchase_requests.status AS status, purchase_requests.is_close AS isClose, purchase_requests.note AS note, currency_centers.symbol AS symbol FROM purchase_requests INNER JOIN `vendors` ON purchase_requests.vendor_id = vendors.id LEFT JOIN currency_centers ON currency_centers.id = purchase_requests.currency_center_id
ORDER BY
${filter.orderBy}
purchase_requests.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM purchase_requests
WHERE is_active = 1 AND name = #{name}
 AND id != #{id}

