mapper.update:
UPDATE purchase_requests SET
   status = -1,
   modified = NOW(),
   modified_by = #{userId}
WHERE id = #{id};

UPDATE purchase_requests SET
  status = 0,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

UPDATE purchase_requests SET
   is_close = #{filter.isClose},
   modified = NOW(),
   modified_by = #{userId}
WHERE id = #{filter.id};

